-- Apply only after CreateStudentAdmissionsAndRecords.sql and
-- CreateStudentPortalAuthentication.sql have been applied and independently verified.
BEGIN;
CREATE SCHEMA IF NOT EXISTS skolenza;

CREATE TABLE IF NOT EXISTS skolenza."StudentRecordDocument" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentId" bigint NOT NULL,
    "RequirementId" bigint NOT NULL,
    "GuardianId" bigint,
    "SubmittedByPortalAccountId" bigint NOT NULL,
    "PersonScope" smallint NOT NULL,
    "VersionNumber" integer NOT NULL,
    "SupersedesDocumentId" bigint,
    "OriginalFileName" varchar(255) NOT NULL,
    "StorageProvider" varchar(30) NOT NULL DEFAULT 'S3',
    "ObjectKey" varchar(1000) NOT NULL,
    "ContentType" varchar(150) NOT NULL,
    "FileSizeBytes" bigint NOT NULL,
    "ChecksumSha256" varchar(64) NOT NULL,
    "ExpiryDate" date,
    "Status" smallint NOT NULL DEFAULT 1,
    "SubmittedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ReviewedByStaffMemberId" bigint,
    "ReviewedDateTime" timestamp,
    "ReviewReason" varchar(1000),
    CONSTRAINT "FK_StudentRecordDocument_Student" FOREIGN KEY ("StudentId") REFERENCES skolenza."Student"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentRecordDocument_Requirement" FOREIGN KEY ("RequirementId") REFERENCES skolenza."StudentDocumentRequirementMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentRecordDocument_Guardian" FOREIGN KEY ("GuardianId") REFERENCES skolenza."Guardian"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentRecordDocument_PortalAccount" FOREIGN KEY ("SubmittedByPortalAccountId") REFERENCES skolenza."StudentPortalAccount"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentRecordDocument_Supersedes" FOREIGN KEY ("SupersedesDocumentId") REFERENCES skolenza."StudentRecordDocument"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentRecordDocument_PersonScope" CHECK ("PersonScope" IN (1, 2)),
    CONSTRAINT "CK_StudentRecordDocument_GuardianScope" CHECK (("PersonScope" = 1 AND "GuardianId" IS NULL) OR ("PersonScope" = 2 AND "GuardianId" IS NOT NULL)),
    CONSTRAINT "CK_StudentRecordDocument_Version" CHECK ("VersionNumber" > 0),
    CONSTRAINT "CK_StudentRecordDocument_Size" CHECK ("FileSizeBytes" > 0),
    CONSTRAINT "CK_StudentRecordDocument_Status" CHECK ("Status" BETWEEN 1 AND 4)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentRecordDocument_Student_Version"
    ON skolenza."StudentRecordDocument" ("InstitutionId", "StudentId", "RequirementId", "PersonScope", "VersionNumber")
    WHERE "GuardianId" IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentRecordDocument_Guardian_Version"
    ON skolenza."StudentRecordDocument" ("InstitutionId", "StudentId", "RequirementId", "PersonScope", "GuardianId", "VersionNumber")
    WHERE "GuardianId" IS NOT NULL;
CREATE INDEX IF NOT EXISTS "IX_StudentRecordDocument_Student_Status"
    ON skolenza."StudentRecordDocument" ("InstitutionId", "StudentId", "Status", "Id");

CREATE TABLE IF NOT EXISTS skolenza."StudentRecordDocumentReviewHistory" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentRecordDocumentId" bigint NOT NULL,
    "FromStatus" smallint NOT NULL,
    "ToStatus" smallint NOT NULL,
    "Reason" varchar(1000),
    "ChangedByStaffMemberId" bigint,
    "ChangedByPortalAccountId" bigint,
    "ChangedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_StudentRecordDocumentReviewHistory_Document" FOREIGN KEY ("StudentRecordDocumentId") REFERENCES skolenza."StudentRecordDocument"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentRecordDocumentReviewHistory_Staff" FOREIGN KEY ("ChangedByStaffMemberId") REFERENCES skolenza."StaffMember"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentRecordDocumentReviewHistory_PortalAccount" FOREIGN KEY ("ChangedByPortalAccountId") REFERENCES skolenza."StudentPortalAccount"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentRecordDocumentReviewHistory_Status" CHECK ("FromStatus" BETWEEN 0 AND 4 AND "ToStatus" BETWEEN 1 AND 4),
    CONSTRAINT "CK_StudentRecordDocumentReviewHistory_Actor" CHECK (("ChangedByStaffMemberId" IS NOT NULL)::integer + ("ChangedByPortalAccountId" IS NOT NULL)::integer = 1)
);
CREATE INDEX IF NOT EXISTS "IX_StudentRecordDocumentReviewHistory_Document"
    ON skolenza."StudentRecordDocumentReviewHistory" ("InstitutionId", "StudentRecordDocumentId", "ChangedDateTime");

COMMIT;
